<?php
require_once __DIR__.'/config.php';require_login();$pdo=db();
if($_SERVER['REQUEST_METHOD']==='POST'){require_admin();verify_csrf();if(($_POST['action']??'')==='delete'){$st=$pdo->prepare('DELETE FROM equipment WHERE id=?');$st->execute([(int)($_POST['id']??0)]);flash('Equipment record deleted.');redirect('equipment.php');}}
$q=trim($_GET['q']??'');$status=trim($_GET['status']??'');$category=trim($_GET['category']??'');
$sql='SELECT * FROM equipment WHERE 1=1';$params=[];
if($q!==''){$sql.=" AND (asset_tag LIKE ? OR name LIKE ? OR serial_number LIKE ? OR ip_address LIKE ? OR location LIKE ? OR manufacturer LIKE ?)";$like='%'.$q.'%';array_push($params,$like,$like,$like,$like,$like,$like);}
if($status!==''){$sql.=' AND status=?';$params[]=$status;}if($category!==''){$sql.=' AND category=?';$params[]=$category;}
if(is_technician()){$sql.=' AND assigned_technician_id=?';$params[]=(int)$_SESSION['user_id'];}
$sql.=' ORDER BY id DESC';$st=$pdo->prepare($sql);$st->execute($params);$rows=$st->fetchAll();$pageTitle='Equipment register';require 'header.php';
?>
<div class="page-heading"><div><div class="eyebrow">ASSET CONTROL</div><h1>Equipment register</h1><p><?=is_technician()?'Equipment assigned to your technician account.':(is_viewer()?'Read-only view of network equipment.':'Search, review and maintain your organization’s network assets.')?></p></div><?php if(is_admin()):?><a class="btn primary" href="equipment_form.php">＋ Add equipment</a><?php endif;?></div><?php show_flash();?>
<section class="panel"><form class="filter-bar" method="get"><div class="search-box"><span>⌕</span><input name="q" value="<?=e($q)?>" placeholder="Search asset, serial, IP address, location…"></div><select name="category"><option value="">All categories</option><?php foreach(categories() as $c):?><option <?=$category===$c?'selected':''?> value="<?=e($c)?>"><?=e($c)?></option><?php endforeach;?></select><select name="status"><option value="">All statuses</option><?php foreach(statuses() as $s):?><option <?=$status===$s?'selected':''?> value="<?=e($s)?>"><?=e($s)?></option><?php endforeach;?></select><button class="btn secondary" type="submit">Filter</button><a class="btn plain" href="equipment.php">Reset</a></form><div class="table-meta"><span><b><?=count($rows)?></b> record(s) found</span><a class="text-link" href="reports.php">View reports →</a></div><div class="table-wrap"><table><thead><tr><th>ASSET DETAILS</th><th>NETWORK</th><th>LOCATION / OWNER</th><th>CONDITION</th><th>STATUS</th><th class="right">ACTIONS</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><div class="asset-cell"><span class="asset-symbol">⌁</span><div><b><?=e($r['name'])?></b><small><?=e($r['asset_tag'])?> · <?=e($r['category'])?></small></div></div></td><td><?=e($r['ip_address']?:'No IP assigned')?><small class="muted"><?=e($r['manufacturer'].' '.$r['model'])?></small></td><td><?=e($r['location']?:'—')?><small class="muted"><?=e($r['assigned_to']?:$r['department']?:'Unassigned')?></small></td><td><?=e($r['condition_note'])?></td><td><?=e($r['status'])?></td><td class="right actions"><?php if(is_admin()):?><a class="action-link" href="equipment_form.php?id=<?=(int)$r['id']?>">Edit</a><form method="post" class="inline-form" onsubmit="return confirm('Delete this equipment record and its maintenance history?')"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="delete"><input type="hidden" name="id" value="<?=(int)$r['id']?>"><button class="action-link danger-link" type="submit">Delete</button></form><?php elseif(is_technician()):?><a class="action-link" href="technician_update.php?id=<?=(int)$r['id']?>">Update status</a><?php endif;?><a class="action-link" href="maintenance.php?equipment_id=<?=(int)$r['id']?>">Service history</a></td></tr><?php endforeach;?><?php if(!$rows):?><tr><td colspan="6" class="empty">No records match your search or assignment.</td></tr><?php endif;?></tbody></table></div></section><?php require 'footer.php';?>